description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Roman_Emperors_Route&oldid=1369018720", "title": "Wikipedia: Roman Emperors Route", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "mass-2026-09-25", "card": null, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Roman_Emperors_Route&oldid=1369018720", "revid": 1369018720, "licence": "CC BY-SA 4.0", "text_sha256": "947fac005a4691bc227e4c493da3449db39c375679769e105fa6582b71154d61", "rev_timestamp": "2026-08-12T11:06:45Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 293, "src": "W", "drop": [[24, 99], [261, 292]], "start": 0}, {"n": 1, "end": 447, "src": "W", "drop": [[407, 446]], "start": 294}, {"n": 1, "end": 573, "src": "W", "drop": [[520, 560]], "start": 448}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Roman_Emperors_Route&oldid=1369018720", "title": "Roman Emperors Route", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01"}}'' restored on Roman Emperors Route', '0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-012", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Emperors Route spans 600 km across Serbia, through the Roman cities of Sirmium, Felix Romuliana and Naissus, in a land where 17 Roman emperors were born."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the route spans 600 km [S1]; the route is in Serbia [S1]; the route includes the Roman cities of Sirmium, Felix Romuliana and Naissus [S3]; 17 Roman emperors were born within Serbia [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Roman Emperors Route is a tourism and archaeology route project in Serbia, not a single fort, tomb or monument [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; The route spans 600 km [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; The sites of the route include the important Roman cities of Sirmium, Felix Romuliana and Naissus [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Sirmium was a city in the Roman province of Pannonia, on the site of modern Sremska Mitrovica in Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Sirmium]; Felix Romuliana is an ancient Roman complex of palaces and temples in Serbia, built by Emperor Galerius [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Felix Romuliana is the Late Roman site Gamzigrad-Romuliana in eastern Serbia [SUPPORTED, no proving quote: https://whc.unesco.org/en/list/1253]; Naissus was a Roman city, the ancient name of the Serbian city of Nis [SUPPORTED: https://en.wikipedia.org/wiki/Ni%C5%A1]; 17 Roman emperors were born in Serbia, and the project''s name derives from that fact [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]; Those 17 Roman emperors were born within the current borders of Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Emperors_Route]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 4;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s034-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s034-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s034-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 4 curated site(s)',
        moved, expected;
END $$;

